INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(118169, 'ruRU', '', 'Используй Укус скалы, чтобы накопить Смерч!', 24330),
(118170, 'ruRU', '', 'У тебя максимум Смерча. Используй Удар лавы!', 24330),
(118171, 'ruRU', '', 'Используй Удар лавы!', 24330),
(118172, 'ruRU', '', 'Удар лавы доступен! Используй его сейчас!', 24330),
(118173, 'ruRU', '', 'Используй Язык пламени!', 24330),
(118174, 'ruRU', '', 'Твой бафф Языка пламени истёк! Используй Язык пламени!', 24330),
(118175, 'ruRU', '', 'Используй Духов волка!', 24330),
(118176, 'ruRU', '', 'Используй Шаровую молнию!', 24330),
(118177, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как шаман усиления.', 24330),
(118178, 'ruRU', '', 'Покажи мне, что ты сражаешься с яростью стихий!', 24330),
(118179, 'ruRU', '', 'Используй Ярость шамана, чтобы снизить получаемый урон.', 24330),
(118180, 'ruRU', '', 'Если ты получаешь слишком много урона в бою, Ярость шамана снижает входящий урон на короткое время. Попробуй!', 24330),
(118181, 'ruRU', '', 'Используй Шаровую молнию, чтобы расправиться с этой группой врагов.', 24330),
(118182, 'ruRU', '', 'Шаровая молния наносит урон всем целям перед тобой. Поражение нескольких врагов усиливает твоё оружие, нанося ещё больше урона!', 24330),
(118183, 'ruRU', '', 'Если ты сражаешься с несколькими врагами, время высвободить всю ярость шторма!', 24330),
(118184, 'ruRU', '', 'Используй Удар шторма прямо сейчас!', 24330),
(118185, 'ruRU', '', 'Используй Удар шторма на тренировочном манекене после срабатывания Буревестника.', 24330),
(118186, 'ruRU', '', 'Старайся использовать Удар шторма каждый раз, когда срабатывает Буревестник.', 24330),
(118187, 'ruRU', '', 'Твоя самая мощная способность, питаемая Смерчем — Удар шторма.', 24330),
(118188, 'ruRU', '', 'Используй Удар лавы на тренировочном манекене.', 24330),
(118189, 'ruRU', '', 'Удар лавы использует Смерч, чтобы зарядить твоё оружие во второй руке лавой, позволяя нанести могучий удар.', 24330),
(118190, 'ruRU', '', 'Использование Укуса скалы накапливает Смерч — ресурс, питающий более мощные атаки.', 24330),
(118191, 'ruRU', '', 'Используй Укус скалы на тренировочном манекене.', 24330),
(118192, 'ruRU', '', 'Укус скалы наделяет твоё оружие силами земли, чтобы наносить урон.', 24330),
(118193, 'ruRU', '', 'Теперь, когда твоё оружие горит, ты можешь сосредоточиться на основной атаке.', 24330),
(118194, 'ruRU', '', 'Используй Язык пламени на тренировочном манекене.', 24330),
(118195, 'ruRU', '', 'Первая атака, которую мы попробуем — Язык пламени, который воспламеняет твоё оружие и обжигает врага огнём.', 24330),
(118196, 'ruRU', '', 'Будучи шаманом усиления, ты направляешь силы стихий прямо в своё оружие, становясь свирепым бойцом ближнего боя, сокрушающим врагов силой пламени, земли и шторма.', 24330),
(118197, 'ruRU', '', 'Используй Камень души, чтобы выжить после смерти.', 24330),
(118198, 'ruRU', '', 'Использование способности Камень души сохраняет саму твою душу на будущее. Не волнуйся, ты всё равно её не использовал! С сохранённой душой ты можешь вернуться из мёртвых по желанию.', 24330),
(118199, 'ruRU', '', 'Хорошо подготовленный чернокнижник может выжить почти в чём угодно... даже в смерти!', 24330),
(118200, 'ruRU', '', 'Потрясающе! Твоё владение демонами дало тебе великую силу!', 24330),
(118201, 'ruRU', '', 'Теперь исцели часть полученного урона с помощью своего Камня здоровья.', 24330),
(118202, 'ruRU', '', 'Теперь исцели часть полученного урона с помощью своего Камня здоровья.', 24330),
(118203, 'ruRU', '', 'Используй Создание камня здоровья.', 24330),
(118204, 'ruRU', '', 'Часть твоей силы можно сплавить в Камень здоровья. Если ты получишь урон, съешь Камень здоровья, чтобы восстановить здоровье.', 24330),
(118205, 'ruRU', '', 'Используй Призыв стража гибели прямо сейчас, чтобы призвать этого демона.', 24330),
(118206, 'ruRU', '', 'Ты не можешь делать это часто, так что сохрани этого демона для крайнего случая.', 24330),
(118207, 'ruRU', '', 'Хотя великих демонов, таких как инферналы и стражи гибели, нельзя контролировать долго, ты можешь призвать одного на свою сторону на короткое время, чтобы он сражался за тебя.', 24330),
(118208, 'ruRU', '', 'Используй Страх, чтобы напугать моего воина.', 24330);
